CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),role text NOT NULL CHECK(role IN('SHOP','WORKER','MANAGER','SUPER_MANAGER','IT')),login_code varchar(4) UNIQUE,email text,password_hash text,status text NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','ACTIVE','DISABLED')),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK((role='SHOP' AND login_code ~ '^00[0-9]{2}$' AND login_code<>'0000') OR (role='WORKER' AND login_code ~ '^[1-9][0-9]{3}$') OR (role IN('MANAGER','SUPER_MANAGER','IT') AND login_code IS NULL)),CHECK(status<>'ACTIVE' OR password_hash IS NOT NULL));
CREATE UNIQUE INDEX backend_email ON accounts(lower(email)) WHERE role IN('MANAGER','SUPER_MANAGER','IT');
CREATE UNIQUE INDEX worker_email ON accounts(lower(email)) WHERE role='WORKER';
CREATE TABLE shops(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL UNIQUE REFERENCES accounts(id),name text NOT NULL,address text NOT NULL,latitude numeric NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude numeric NOT NULL CHECK(longitude BETWEEN -180 AND 180));
CREATE TABLE workers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL UNIQUE REFERENCES accounts(id),contact text,address text,timesheet_frequency text);
CREATE TABLE account_shops(account_id uuid REFERENCES accounts(id),shop_id uuid REFERENCES shops(id),PRIMARY KEY(account_id,shop_id));
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE password_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid NOT NULL REFERENCES accounts(id),purpose text NOT NULL,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,revoked_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE api_operations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_account_id uuid REFERENCES accounts(id),operation_id uuid NOT NULL,request_hash text NOT NULL,response_data jsonb,created_at timestamptz DEFAULT now(),UNIQUE(actor_account_id,operation_id));
CREATE TABLE photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),uploaded_by_account_id uuid REFERENCES accounts(id),storage_key text UNIQUE NOT NULL,status text NOT NULL,media_type text,byte_size bigint,created_at timestamptz DEFAULT now());
CREATE TABLE attendance_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),worker_id uuid NOT NULL REFERENCES workers(id),shop_id uuid NOT NULL REFERENCES shops(id),submitted_by_account_id uuid NOT NULL REFERENCES accounts(id),sign_type text NOT NULL CHECK(sign_type IN('SIGN_IN','SIGN_OUT')),source text NOT NULL,original_occurred_at timestamptz NOT NULL,planned_start_at timestamptz,effective_occurred_at timestamptz NOT NULL,confirmed_occurred_at timestamptz,effective_deleted boolean NOT NULL DEFAULT false,confirmed_deleted boolean NOT NULL DEFAULT false,offline boolean NOT NULL DEFAULT false,camera_status text NOT NULL,photo_id uuid UNIQUE REFERENCES photos(id),location jsonb,version integer NOT NULL DEFAULT 1,received_at timestamptz NOT NULL DEFAULT now(),CHECK(sign_type='SIGN_IN' OR planned_start_at IS NULL));
CREATE INDEX record_scope ON attendance_records(shop_id,worker_id,effective_occurred_at);
CREATE TABLE attendance_adjustments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),record_id uuid NOT NULL REFERENCES attendance_records(id),actor_account_id uuid NOT NULL REFERENCES accounts(id),source text NOT NULL,action text NOT NULL,before_at timestamptz,after_at timestamptz,status text NOT NULL DEFAULT 'PENDING',base_version integer NOT NULL,created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX one_plan ON attendance_adjustments(record_id) WHERE source='PLANNED_START';
CREATE TABLE attendance_validations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),adjustment_id uuid NOT NULL UNIQUE REFERENCES attendance_adjustments(id),validated_by_account_id uuid NOT NULL REFERENCES accounts(id),decision text NOT NULL,previous_confirmed_at timestamptz,resulting_confirmed_at timestamptz,validated_at timestamptz DEFAULT now());
CREATE TABLE work_segments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),worker_id uuid NOT NULL REFERENCES workers(id),shop_id uuid NOT NULL REFERENCES shops(id),sign_in_record_id uuid REFERENCES attendance_records(id),sign_out_record_id uuid REFERENCES attendance_records(id),start_at timestamptz,end_at timestamptz,duration_minutes numeric,hrs numeric(6,2),status text NOT NULL,issue_code text,CHECK(status<>'CONFIRMED' OR (start_at IS NOT NULL AND end_at IS NOT NULL AND end_at>=start_at AND hrs IS NOT NULL)));
CREATE TABLE report_exports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requested_by_account_id uuid NOT NULL REFERENCES accounts(id),filters jsonb NOT NULL,snapshot_data jsonb NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE email_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),account_id uuid REFERENCES accounts(id),password_link_id uuid REFERENCES password_links(id),recipient_email text NOT NULL,encrypted_payload text,status text DEFAULT 'QUEUED',attempt_count integer DEFAULT 0,next_attempt_at timestamptz DEFAULT now(),lease_expires_at timestamptz,last_error_code text,sent_at timestamptz,created_at timestamptz DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_account_id uuid REFERENCES accounts(id),action text NOT NULL,resource_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz DEFAULT now());
